mapper.update:
UPDATE source_sync_runs SET finished_at = now(), status = #{status}, error = #{error},
        created_docs = #{createdDocs}, updated_docs = #{updatedDocs}
 WHERE id = #{id}

mapper.delete:
DELETE FROM source_sync_runs WHERE source_id = #{sourceId} AND id NOT IN
 (SELECT id FROM source_sync_runs WHERE source_id = #{sourceId}
  ORDER BY started_at DESC LIMIT 50)

mapper.select:
SELECT id, started_at, finished_at, status, created_docs, updated_docs, error
 FROM source_sync_runs WHERE source_id = #{sourceId}
 ORDER BY started_at DESC LIMIT #{limit}
